<?php defined('AFAQ') || exit; $e = function ($k) use ($err) { return isset($err[$k]) ? '<small class="form-error">' . h($err[$k]) . '</small>' : ''; }; ?>
<section class="section"><div class="container stack gap8"><div class="stack gap3"><span class="eyebrow">Get in touch</span><h1 class="h1">Contact us</h1></div><div class="contact-grid">
<div class="panel"><?php if ($f && $f[1]): ?><p role="status" class="form-ok h3"><?= h($f[0]) ?></p><?php else: ?><form method="post" class="stack gap4" novalidate><?= csrf() ?>
<?php if ($f): ?><p role="alert" class="form-error"><?= h($f[0]) ?></p><?php endif; ?>
<label class="field"><span>Name</span><input name="name" value="<?= h($v['name']) ?>" autocomplete="name" required><?= $e('name') ?></label>
<div class="form-grid"><label class="field"><span>Phone</span><input name="phone" type="tel" value="<?= h($v['phone']) ?>" autocomplete="tel"><?= $e('phone') ?></label><label class="field"><span>Email</span><input name="email" type="email" value="<?= h($v['email']) ?>" autocomplete="email"><?= $e('email') ?></label></div>
<label class="field"><span>Message</span><textarea name="message" rows="5" required><?= h($v['message']) ?></textarea><?= $e('message') ?></label>
<div class="hp" aria-hidden="true"><label>Website<input name="website" tabindex="-1" autocomplete="off"></label></div><?= $e('form') ?><div><button class="btn btn-primary" type="submit">Send message</button></div></form><?php endif; ?></div>
<div class="stack gap4"><h2 class="h3"><?= h($S['company']) ?></h2><?php if ($S['address']): ?><p><?= h($S['address']) ?></p><?php endif; ?><?php if ($S['phone']): ?><p><a href="tel:<?= h(preg_replace('/[^\d+]/', '', $S['phone'])) ?>"><?= h($S['phone']) ?></a></p><?php endif; ?><?php if ($S['email']): ?><p><a href="mailto:<?= h($S['email']) ?>"><?= h($S['email']) ?></a></p><?php endif; ?><?php if ($S['hours']): ?><p class="small muted"><?= h($S['hours']) ?></p><?php endif; ?><?php if ($S['maps'] && preg_match('#^https?://#i', $S['maps'])): ?><p><a class="btn btn-outline" href="<?= h($S['maps']) ?>" target="_blank" rel="noopener noreferrer">Open in Google Maps</a></p><?php endif; ?></div></div></div></section>
